# Netlist builder for the logic-gate simulator.
class NL:
    def __init__(self):
        self.defs = {}          # id -> rhs string
        self.n = 0
        self.regs = []          # list of (reg_id, ) reserved; next set later
        self._c0 = None
        self._c1 = None
    def _alloc(self):
        i = self.n; self.n += 1; return i
    # combinational primitives (id must exceed input ids; we allocate after)
    def _emit(self, rhs):
        i = self._alloc(); self.defs[i] = rhs; return i
    def const0(self):
        if self._c0 is None: self._c0 = self._emit("0")
        return self._c0
    def const1(self):
        if self._c1 is None: self._c1 = self._emit("1")
        return self._c1
    def NOT(self,a): return self._emit(f"~out{a}")
    def AND(self,a,b): return self._emit(f"out{a} & out{b}")
    def OR(self,a,b): return self._emit(f"out{a} | out{b}")
    def XOR(self,a,b): return self._emit(f"out{a} ^ out{b}")
    def COPY(self,a): return self._emit(f"out{a}")
    # register: reserve an id now (low), tie later
    def reg(self):
        i = self._alloc(); self.regs.append(i); self.defs[i]=None; return i
    def tie(self, reg_id, next_id):
        self.defs[reg_id] = f"out{next_id}"   # reg = COPY(next) -> delayed (reg<next)
    # helpers
    def mux(self, sel, if1, if0):
        # sel? if1 : if0
        nsel = self.NOT(sel)
        return self.OR(self.AND(sel,if1), self.AND(nsel,if0))
    def dump(self, path):
        # ensure contiguous 0..n-1 all defined
        with open(path,"w") as f:
            for i in range(self.n):
                rhs = self.defs.get(i)
                if rhs is None:
                    rhs = "0"
                f.write(f"out{i} = {rhs}\n")
    def count(self):
        return self.n
PYEOF
