class NL:
    def __init__(self):
        self.defs={}; self.n=0; self.regs=[]
        self._c0=None; self._c1=None
    def _alloc(self): i=self.n; self.n+=1; return i
    def _emit(self,rhs): i=self._alloc(); self.defs[i]=rhs; return i
    def const0(self):
        if self._c0 is None: self._c0=self._emit("0")
        return self._c0
    def const1(self):
        if self._c1 is None: self._c1=self._emit("1")
        return self._c1
    def cval(self,a):
        if a==self._c0: return 0
        if a==self._c1: return 1
        return None
    def NOT(self,a):
        v=self.cval(a)
        if v==0: return self.const1()
        if v==1: return self.const0()
        return self._emit(f"~out{a}")
    def AND(self,a,b):
        va,vb=self.cval(a),self.cval(b)
        if va==0 or vb==0: return self.const0()
        if va==1: return b
        if vb==1: return a
        if a==b: return a
        return self._emit(f"out{a} & out{b}")
    def OR(self,a,b):
        va,vb=self.cval(a),self.cval(b)
        if va==1 or vb==1: return self.const1()
        if va==0: return b
        if vb==0: return a
        if a==b: return a
        return self._emit(f"out{a} | out{b}")
    def XOR(self,a,b):
        va,vb=self.cval(a),self.cval(b)
        if va==0: return b
        if vb==0: return a
        if va==1: return self.NOT(b)
        if vb==1: return self.NOT(a)
        if a==b: return self.const0()
        return self._emit(f"out{a} ^ out{b}")
    def COPY(self,a):
        # force a fresh signal (used for outputs); no fold
        return self._emit(f"out{a}")
