import math,random,subprocess
M=2**32
def fib(n):
    a,b=0,1
    for _ in range(n): a,b=b,(a+b)&0xFFFFFFFF
    return a
def want(N): return fib(math.isqrt(N))&0xFFFFFFFF
tests=set([0,1,2,3,4,208,20000,M-1])
for k in range(0,65536): # perfect squares and boundaries
    for d in (-1,0,1):
        v=k*k+d
        if 0<=v<M: tests.add(v)
tests|= {random.randint(0,M-1) for _ in range(200)}
bad=0
for n in sorted(tests):
    r=int(subprocess.run(['./sim',str(n)],capture_output=True,text=True).stdout)
    if r!=want(n): bad+=1; print('MISMATCH',n,r,want(n))
print('total',len(tests),'bad',bad)
"

